package com.igviewer.archive.data

import org.junit.Assert.assertEquals
import org.junit.Assert.assertNotNull
import org.junit.Test
import java.io.File
import java.nio.file.Files

/**
 * Instagram exports sometimes store a photo under a bare timestamp with no file
 * extension, while the JSON still references it as `....jpg`. The media must resolve
 * (by name-minus-extension) and render. Generated bytes only -- no real data.
 */
class ExtensionlessMediaTest {

    private val jpegHeader = byteArrayOf(0xFF.toByte(), 0xD8.toByte(), 0xFF.toByte(), 0xE0.toByte(), 0, 0, 0, 0)

    @Test
    fun resolves_and_renders_extensionless_photos() {
        val root = Files.createTempDirectory("extexport").toFile()
        val thread = File(root, "your_instagram_activity/messages/inbox/extthread")
        val photos = File(thread, "photos")
        photos.mkdirs()
        // Case A: URI says ".jpg", the file on disk has no extension.
        File(photos, "384312553936495").writeBytes(jpegHeader)
        // Case B: neither the URI nor the file has an extension (classified by sniffing).
        File(photos, "1118482956833413").writeBytes(jpegHeader)

        File(thread, "message_1.json").writeText(
            """
            {
              "participants": [{"name": "me"}, {"name": "Other Person"}],
              "title": "extthread",
              "messages": [
                {
                  "sender_name": "Other Person",
                  "timestamp_ms": 1704423612345,
                  "photos": [{"uri": "your_instagram_activity/messages/inbox/extthread/photos/384312553936495.jpg"}]
                },
                {
                  "sender_name": "me",
                  "timestamp_ms": 1704423612346,
                  "photos": [{"uri": "your_instagram_activity/messages/inbox/extthread/photos/1118482956833413"}]
                }
              ]
            }
            """.trimIndent(),
        )

        val index = ArchiveIndex.index(root)
        assertEquals("no file should fail to parse", 0, index.parseFailures)

        // Case A: referenced with ".jpg" but the file has no extension -> stem match.
        val withExt = index.mediaFile(
            "your_instagram_activity/messages/inbox/extthread/photos/384312553936495.jpg",
        )
        assertNotNull("extensionless file must resolve via stem match", withExt)
        assertEquals("384312553936495", withExt!!.name)

        val items = UiMapping.messageItems(index, "extthread")
        assertEquals("both media-only messages kept", 2, items.size)
        assertEquals("case A renders", 1, items[0].imageFiles.size)
        assertEquals("case B renders", 1, items[1].imageFiles.size)
        assertEquals(withExt.absolutePath, items[0].imageFiles[0])
    }
}
